Method.Implementation:
    $$$TRACE("TwWebServiceSoap call web service " _ pRequest.ClinFileNm _", " _ pRequest.InXDRTouchWorksPnRFileNm _ " with new Msg Id: " _ $EXTRACT(pRequest.clinID, 1, 12))
    set pResponse = ##class(Ens.StringResponse).%New()

    If ##class(%File).Exists(pRequest.InXDRTouchWorksPnRFileNm)
    {
		try {

		    #dim httpRequest As %Net.HttpRequest
			set httpRequest = ##class(%Net.HttpRequest).%New()
		  	Set file=##class(%File).%New(pRequest.InXDRTouchWorksPnRFileNm)
			Write file.Size

			Set stream=##class(%Stream.FileBinary).%New()
			Set sc=stream.LinkToFile(pRequest.InXDRTouchWorksPnRFileNm)

			Do httpRequest.EntityBody.CopyFromAndSave(stream)

		    $$$TRACE( "EntityBody.Size: " _ httpRequest.EntityBody.Size )


			Do httpRequest.SetParam("OID", pRequest.OID) 
			Do httpRequest.SetParam("Community", pRequest.Community)
			Do httpRequest.SetParam("Direction", pRequest.Direction)

			set port=443


			do httpRequest.SetHeader("Host","https://" _ ..HOST)			
			set httpRequest.HTTPVersion = "1.1"

			set httpRequest.Timeout=30
			set httpRequest.Port=port
			set httpRequest.Server=..HOST

			do httpRequest.SetHeader("Content-Type","multipart/related; type=""application/xop+xml""; start-info=""application/soap+xml""; start=""<http://tempuri.org/0>""; boundary=""uuid:"_ pRequest.Boundary _ """")
			do httpRequest.SetHeader("Expect","100-continue")
			do httpRequest.SetHeader("Accept", "*/*")
			do httpRequest.SetHeader("Accept-Encoding","gzip, deflate")
			do httpRequest.SetHeader("Connection","Keep-Alive")
			do httpRequest.SetHeader("MIME-Version", "1.0")
			set httpRequest.SSLConfiguration = "AllScripts"
			set httpRequest.Https = 1



			set stat = httpRequest.Post(..SERVICENAME)
			$$$TRACE( "Called WS: " _ ..SERVICENAME _ " on " _..HOST _ ", Status: " _ stat)
			if ((stat = 1) && (httpRequest.HttpResponse.StatusCode = 200))
        	{

				$$$TRACE( "RESPONSE: " _ httpRequest.HttpResponse.StatusCode _ ", " _ httpRequest.HttpResponse.StatusLine)
				set pResponse.StringValue = httpRequest.HttpResponse.StatusCode _ ", " _ httpRequest.HttpResponse.StatusLine
				set stream = httpRequest.HttpResponse.Data
				While 'stream.AtEnd 
				{ 
					set outStr = stream.ReadLine(,.sc,.eol)
					$$$TRACE( outStr )
					set pResponse.StringValue = pResponse.StringValue _ outStr _";"
					If $$$ISERR(sc) 
					{ 
						$$$TRACE( "ERROR") Quit 
					} 

				}
			}
        	else
        	{
		        if (httpRequest.HttpResponse.StatusLine [ "SSL_ERROR_SYSCALL")
	        	{

		        		Set stat = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName, "Retry the message: Error: SSL_ERROR_SYSCALL "_ httpRequest.HttpResponse.StatusCode _ ", " _ httpRequest.HttpResponse.StatusLine)	

	        	}
	        	else
	        	{
		              	set stat = $$$ERROR($$$GeneralError, "Invalid Response from Http call: " _ httpRequest.HttpResponse.StatusCode _ ", " _ httpRequest.HttpResponse.StatusLine)
	        	}
        	}
		}
		CATCH err {		
		    $$$LOGERROR( "Error while Executing: "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
		    set tSC = $$$ERROR( "Exception "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
		}	

    }
    else
    {
	    set stat = $$$ERROR($$$GeneralError, "Data file: " _ pRequest.InXDRTouchWorksPnRFileNm _" not found, error: " _ stat)
    }

 QUIT stat
